<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>System Interface</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background-color: #050505;
      color: #fff;
      font-family: "Courier New", Courier, monospace;
      height: 100vh;
      width: 100vw;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      position: relative;
    }

    /* --- Floating Background Keywords --- */
    .animation-container {
      position: fixed;
      inset: 0;
      width: 100vw;
      height: 100vh;
      pointer-events: none;
      overflow: hidden;
      z-index: 2;
    }

    .animation-container span {
      position: absolute;
      bottom: -40px;
      color: #ff1a40 !important;
      font-family: "Courier New", Courier, monospace;
      font-weight: 900;
      white-space: nowrap;
      user-select: none;
      animation-name: floatUp;
      animation-timing-function: linear;
      animation-fill-mode: forwards;
      text-shadow: 0 0 10px #ff0033, 0 0 20px #ff0033, 0 0 30px #ff0033;
    }

    @keyframes floatUp {
      0% {
        transform: translateY(0);
        opacity: 0;
      }
      10% {
        opacity: 0.9;
      }
      90% {
        opacity: 0.9;
      }
      100% {
        transform: translateY(-110vh);
        opacity: 0;
      }
    }

    /* --- Kernel Boot Terminal Screen --- */
    #boot-container {
      width: 100vw;
      height: 100vh;
      padding: 24px;
      font-size: 14px;
      line-height: 1.6;
      white-space: pre-wrap;
      word-break: break-word;
      overflow: hidden;
      background: #050505;
      position: relative;
      z-index: 20;
    }

    .ok {
      color: #00ff66;
      font-weight: bold;
    }

    .bracket {
      color: #888;
    }

    .msg {
      color: #e0e0e0;
    }

    .cursor {
      display: inline-block;
      width: 8px;
      height: 15px;
      background: #00ff66;
      vertical-align: text-bottom;
      animation: blink 0.8s infinite;
    }

    @keyframes blink {
      0%, 49% { opacity: 1; }
      50%, 100% { opacity: 0; }
    }

    /* --- Main Page Container --- */
    #main-content {
      display: none;
      opacity: 0;
      transition: opacity 1.2s ease-in-out;
      height: 100vh;
      width: 100vw;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      text-align: center;
      padding: 10px 16px;
      position: relative;
      z-index: 10;
    }

    /* Clean Subtle Badge */
    .badge {
      display: inline-block;
      background: rgba(255, 0, 51, 0.12);
      border: 1px solid #cc0029;
      color: #ff3355;
      padding: 5px 14px;
      font-size: 12px;
      font-weight: bold;
      letter-spacing: 2px;
      text-transform: uppercase;
      border-radius: 4px;
      margin-bottom: 8px;
    }

    /* Crisp Red Heading */
    h1 {
      font-size: clamp(1.8rem, 3.5vw, 2.6rem);
      color: #ff1a40 !important;
      font-weight: bold;
      text-transform: uppercase;
      letter-spacing: 3px;
      margin-bottom: 6px;
      text-shadow: 0 0 6px rgba(255, 26, 64, 0.5);
    }

    /* --- Pure White High-Contrast Scramble Text --- */
    .text {
      font-size: 1.05rem;
      font-weight: 700;
      color: #ffffff !important;
      margin-bottom: 12px;
      min-height: 1.6em;
      max-width: 850px;
      display: inline-block;
      text-shadow: 0 0 8px rgba(255, 255, 255, 0.6), 0 0 15px rgba(255, 255, 255, 0.2);
    }

    .dud {
      color: #ff2a4b !important;
      font-weight: bold;
      text-shadow: 0 0 6px #ff0033;
    }

    /* --- ASCII Art Wrapper & Brightness Enhancement --- */
    .art-container {
      max-width: 90vw;
      max-height: 58vh;
      overflow: hidden !important;
      background-color: #000;
      border: 1.5px solid #2a2a2a;
      border-radius: 6px;
      padding: 12px 18px;
      box-shadow: 0 0 30px rgba(0, 0, 0, 0.95);
      margin-bottom: 8px;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .ascii {
      display: inline-block !important;
      white-space: pre !important;
      letter-spacing: 0 !important;
      line-height: 1 !important;
      font-family: 'Consolas', 'BitstreamVeraSansMono', 'CourierNew', Courier, monospace !important;
      font-size: 9px !important;
      border: none !important;
      
      /* Boosts dark/gloomy text to bright, vivid tones */
      filter: brightness(1.75) contrast(1.4) drop-shadow(0 0 1px rgba(255, 255, 255, 0.2));
    }

    code span span {
      display: inline-block !important;
      width: 5.5px !important;
      height: 10px !important;
      line-height: 10px !important;
      text-align: center;
      vertical-align: top !important;
    }

    .footer-note {
      font-size: 11px;
      color: #777;
      margin-top: 6px;
      letter-spacing: 1px;
    }
  </style>
</head>
<body>

  <!-- 1. Kernel Boot Sequence -->
  <div id="boot-container">
    <div id="boot-log"></div>
    <span class="cursor" id="cursor"></span>
  </div>

  <!-- 2. Main Page Layout -->
