  <script>
    /* --- Boot Sequence Handler --- */
    const bootLines = [
      "Applying INTEL CPU microcode update",
      "Checking for hardware changes",
      "Bringing up interface eth0",
      "Determining IP information for eth0... done.",
      "Connecting to backend service",
      "Connected to backend service",
      "Finding CTF database services",
      "Services found on port 3306",
      "Establishing connection to the database",
      "Connection established",
      "Logging into the database server",
      "Login successful",
      "Reading database",
      "Fetching data from database",
      "Data acquired",
      "Finding other resources",
      "Fetching resources",
      "Processing DOM",
      "Loading images",
      "Loading content",
      "Page rendered",
      "Starting display manager",
      "WELCOME TO SYSTEM CORE",
      "Initializing execution environment..."
    ];

    const logContainer = document.getElementById("boot-log");
    const bootScreen = document.getElementById("boot-container");
    const mainScreen = document.getElementById("main-content");

    let lineIndex = 0;

    function printNextLine() {
      if (lineIndex < bootLines.length) {
        const line = document.createElement("div");
        line.innerHTML = `<span class="bracket">[ </span><span class="ok">OK</span><span class="bracket"> ]</span> <span class="msg">${bootLines[lineIndex]}</span>`;
        logContainer.appendChild(line);

        window.scrollTo(0, document.body.scrollHeight);
        lineIndex++;

        const delay = Math.floor(Math.random() * 35) + 15;
        setTimeout(printNextLine, delay);
      } else {
        setTimeout(showMainPage, 400);
      }
    }

    function showMainPage() {
      bootScreen.style.display = "none";
      mainScreen.style.display = "flex";
      setTimeout(() => {
        mainScreen.style.opacity = "1";
        startScrambleEffect();
        app.init();
      }, 50);
    }

    window.addEventListener("DOMContentLoaded", () => {
      setTimeout(printNextLine, 100);
    });

    /* --- Text Scramble Engine --- */
    class TextScramble {
      constructor(el) {
        this.el = el;
        this.chars = '!@#$%^&*()_-=+{}:"|<>?,./;';
        this.update = this.update.bind(this);
      }
      setText(newText) {
        const oldText = this.el.innerText;
        const length = Math.max(oldText.length, newText.length);
        const promise = new Promise((resolve) => this.resolve = resolve);
        this.queue = [];
        for (let i = 0; i < length; i++) {
          const from = oldText[i] || '';
          const to = newText[i] || '';
          const start = Math.floor(Math.random() * 30);
          const end = start + Math.floor(Math.random() * 30);
          this.queue.push({ from, to, start, end });
        }
        cancelAnimationFrame(this.frameRequest);
        this.frame = 0;
        this.update();
        return promise;
      }
      update() {
        let output = '';
        let complete = 0;
        for (let i = 0, n = this.queue.length; i < n; i++) {
          let { from, to, start, end, char } = this.queue[i];
          if (this.frame >= end) {
            complete++;
            output += to;
          } else if (this.frame >= start) {
            if (!char || Math.random() < 0.28) {
              char = this.randomChar();
              this.queue[i].char = char;
            }
            output += `<span class="dud">${char}</span>`;
          } else {
            output += from;
          }
        }
        this.el.innerHTML = output;
        if (complete === this.queue.length) {
          this.resolve();
        } else {
          this.frameRequest = requestAnimationFrame(this.update);
          this.frame++;
        }
      }
      randomChar() {
        return this.chars[Math.floor(Math.random() * this.chars.length)];
      }
    }

    const phrases = [
      'Yes, We are criminal.',
      'Our crime is our curiosity.',
      'Our crime is that of judging people by what they say and think, not what they look like.',
      'Our crime is that of outsmarting you, something that you will never forgive us for.',
      'We are hackers, and this is our manifesto.',
      'You may stop this individual, but you cant stop us all...',
      'after all, were all alike.'
    ];

    function startScrambleEffect() {
      const el = document.querySelector('.text');
      const fx = new TextScramble(el);
      let counter = 0;
      const next = () => {
        fx.setText(phrases[counter]).then(() => {
          setTimeout(next, 2500);
        });
        counter = (counter + 1) % phrases.length;
      };
      next();
    }

    /* --- Floating Background Words Engine --- */
    var app = {
      chars: ['Lazy Hackers', 'Seized', '127.0.0.1', '1337', '0x523344', 'Localhost', 'nullqi', 'HACKED!', 'Security', 'Breached!', 'System'],

      init: function () {
        app.container = document.createElement('div');
        app.container.className = 'animation-container';
        document.body.appendChild(app.container);
        window.setInterval(app.add, 200);
      },

      add: function () {
        var element = document.createElement('span');
        app.container.appendChild(element);
        app.animate(element);
      },

      animate: function (element) {
        var character = app.chars[Math.floor(Math.random() * app.chars.length)];
        var duration = Math.floor(Math.random() * 8) + 6;
        var offset = Math.floor(Math.random() * 92) + 4;
        var size = 12 + Math.floor(Math.random() * 8);
        element.style.cssText = 'left:' + offset + 'vw; font-size:' + size + 'px; animation-duration:' + duration + 's;';
        element.innerHTML = character;
        window.setTimeout(app.remove, duration * 1000, element);
      },

      remove: function (element) {
        if (element && element.parentNode) {
          element.parentNode.removeChild(element);
        }
      }
    };
  </script>
